# ============= tests/test_ai/test_optimizer.py =============\n\"\"\"Tests for AI Optimizer\"\"\"\nimport pytest\nimport numpy as np\nfrom src.ai.optimizer import IrrigationOptimizer\n\n\ndef test_optimizer_initialization():\n    \"\"\"Test optimizer initialization\"\"\"\n    optimizer = IrrigationOptimizer()\n    assert optimizer.model is not None\n    assert not optimizer.is_trained\n\n\ndef test_optimizer_training():\n    \"\"\"Test model training\"\"\"\n    optimizer = IrrigationOptimizer()\n\n    # Generate sample data\n    X = np.random.rand(100, 5)\n    y = np.random.rand(100)\n\n    optimizer.train(X, y)\n    assert optimizer.is_trained\n\n\ndef test_optimizer_optimization():\n    \"\"\"Test irrigation optimization\"\"\"\n    optimizer = IrrigationOptimizer()\n\n    # Test with untrained model (should use fallback)\n    result = optimizer.optimize_irrigation(\n        soil_moisture=0.3,\n        etc=5.0,\n        crop_stage=2,\n        weather_forecast=[20, 22, 24, 25, 26, 23, 21]\n    )\n    assert result >= 0  # Should not be negative
